head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05031";
scwin.SELECT = 2;
scwin.form = null;

// as-is 공용 상수 — 셸이 js/elw.js 를 싣지 않아 화면에 선언한다(KRX 합의 대상).

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05031.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_ElwPreDataDownload", fn: function(){ return ((dma_readDataVO.get("listBzTpCd") ?? (() => { throw new Error("unresolved:" + "readDataVO.listBzTpCd"); })()) === '002'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.prelistPageForm || { elements: [] });
        $c.util.getComponent("dma_ElwMstReq").set("bzCd", BZ_USRLST);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05031.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_fn_ElwMst, tx_fn_ElwPreDataDownload) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05031.btn_Search_onclick' }); }
};

/**
 * @method
 * @name slc_currentPageSize_onchange
 * @description slc_currentPageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_currentPageSize_onchange = async function(e){
    try {
        await scwin.search();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05031.slc_currentPageSize_onchange' }); }
};

/**
 * @method
 * @name grd_pageList_oncellclick
 * @description grd_pageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_pageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_pageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_pageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.elwMst(r["isuCd"], r["bzProcsNo"], r["listBzTpCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_pageList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_ElwPreDataDownload_onclick
 * @description 「예비심사청구 데이터 다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ElwPreDataDownload_onclick = async function(e){
    try {
        await scwin.elwPreDataDownload()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05031.btn_ElwPreDataDownload_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_111_onclick
 * @description krxpage_pagenavigator_111 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_111_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_ElwMstReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil05031.krxpage_pagenavigator_111_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_ElwMst
 * @description Elw Mst 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwMst = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwMst",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_ElwMstReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_ElwPreDataDownload
 * @description Elw Pre Data Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ElwPreDataDownload = async function () {
    const sbmOptions = {
        id: "tx_fn_ElwPreDataDownload",
        method: "post",
        action: "/list/elw.do",
        ref: "dma_ElwPreDataDownloadReq",
        target: "dlt_pageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name elwMst
 * @description elw Mst 처리
 * @param {String} isuCd isuCd
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} listBzTpCd listBzTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwMst = async function (isuCd, bzProcsNo, listBzTpCd) {
    $c.util.getComponent("dma_ElwMstReq").set("transKind", scwin.SELECT);
    $c.util.getComponent('dma_ElwMstReq').set('isuCd', isuCd);
    $c.util.getComponent('dma_ElwMstReq').set('bzProcsNo', bzProcsNo);
    $c.util.getComponent("slc_listBzTpCd").setValue(listBzTpCd);
    fn_clearTransTbl();
    fn_setBzCd();
    fn_setMainPage();
    scwin.form.action = '/list/elw.do';
    $c.util.getComponent('dma_ElwMstReq').set('method', 'searchElw');
    await scwin.tx_fn_ElwMst();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPageSearch');
    await moveUrl('/list/elw.do', {});
};

/**
 * @method
 * @name elwPreDataDownload
 * @description elw Pre Data Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.elwPreDataDownload = async function () {
    if (await $c.win.confirm("검색기간(" + $c.util.getComponent('cal_listBzApplDdTm1').getValue()+ " ~ " + $c.util.getComponent('cal_listBzApplDdTm2').getValue()+ ") 내에 신청한\n『상장예비심사청구』내역을 전체 다운로드합니다.")) {
        scwin.form.action = '/list/elw.do';
        $c.util.getComponent('dma_ElwMstReq').set('method', 'elwPreDataDownload');
        await scwin.tx_fn_ElwPreDataDownload();
    } else {
        return;
    }
};
